if(isset($_FILES['screenshots']))foreach($_FILES['screenshots']['tmp_name'] as $i=>$tmp){if($_FILES['screenshots']['error'][$i]!==UPLOAD_ERR_OK||!is_uploaded_file($tmp)||$_FILES['screenshots']['size'][$i]>5242880)continue;$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)continue;$fn=bin2hex(random_bytes(16)).'.'.$ext;if(move_uploaded_file($tmp,__DIR__.'/uploads/screenshots/'.$fn))db()->prepare("INSERT INTO screenshots(app_id,filename) VALUES(?,?)")->execute([$id,$fn]);}}
$s=db()->prepare("SELECT * FROM screenshots WHERE app_id=?");$s->execute([$id]);$imgs=$s->fetchAll();$pageTitle='Chỉnh sửa ứng dụng';require __DIR__.'/includes/header.php';?><div class="formbox"><h1>Chỉnh sửa ứng dụng</h1><p class="error"><?=e($err)?></p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Tên</label><input name="name" required value="<?=e($a['name'])?>"><label>Danh mục</label><input name="category" required value="<?=e($a['category'])?>"><label>Mô tả ngắn</label><input name="short_description" value="<?=e($a['short_description'])?>"><label>Mô tả</label><textarea name="description" rows="6"><?=e($a['description'])?></textarea><label>Link tải</label><input type="url" name="download_url" value="<?=e($a['download_url'])?>"><label>Trạng thái</label><select name="status"><option value="draft" <?=$a['status']==='draft'?'selected':''?>>Bản nháp</option><option value="published" <?=$a['status']==='published'?'selected':''?>>Công khai</option></select><label>Ảnh chụp (JPG/PNG/WebP, 5MB mỗi ảnh)</label><input type="file" name="screenshots[]" accept="image/jpeg,image/png,image/webp" multiple><button class="btn">Lưu thay đổi</button></form><h2>Ảnh hiện tại</h2><div class="screens"><?php foreach($imgs as $im):?><div><img src="<?=e('uploads/screenshots/'.$im['filename'])?>" alt=""><form method="post" action="admin_delete_screenshot.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$im['id']?>"><button class="link">Xóa ảnh</button></form></div><?php endforeach;?></div></div></main></body></html>